// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        // Ensure value is not exactly 10 ether
        vm.assume(value != 10 ether);
        // Record the sender's balance before the call
        uint256 senderBalanceBefore = address(this).balance;
        // Try to send exactly 'value' wei to the contract
        (bool success, ) = address(c).call{value: value}("");
        // The reference C should always revert when value != 10 ether
        assertTrue(!success);
        // The sender's balance should be unchanged because the call reverted
        assertTrue(address(this).balance == senderBalanceBefore);
    }
}

